insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21c693ec-ce2c-4a1c-b6a4-e5c07cc9e39f', 'fr', 'Elle doit deviner une partie de ce que tu dis parce que tu parles trop bas. Qu’est-ce que ça crée ?', '["Une forte attirance immédiate", "Une présence parfaitement ajustée", "Un air mystérieux et intrigant", "Une friction qui casse la fluidité"]'::jsonb, 'Un manque de clarté ajoute une tension inutile à l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21ca0984-0243-415e-ab95-8d472e631a12', 'fr', 'Tu t’approches d’une femme assise en terrasse. Quels mouvements montrent l’aisance ?', '["Des petits pas pressés, les épaules voûtées", "Les bras raides le long du corps, une démarche crispée", "Un pas régulier, les bras qui se balancent naturellement, une posture droite", "Des pas hésitants, le regard rivé au sol"]'::jsonb, 'Un mouvement détendu transmet la sécurité et lui rend l’échange plus facile.')
