insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fa1ad2f-3496-4f7e-b850-7253ba88fd6b', 'fr', 'Elle rit à ton accroche, se tourne complètement vers toi, mais croise les bras. Que se passe-t-il ?', '["Ouverture : son rire et sa posture montrent de l’intérêt malgré les bras croisés", "Politesse : un rire forcé avec un corps fermé veut dire désintérêt", "Mitigé : rire et se tourner vers toi, c’est de l’ouverture, mais les bras croisés trahissent une incertitude"]'::jsonb, 'Le rire montre qu’elle est à l’aise, les bras croisés une réserve ; continue avec légèreté.')
