insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3583c492-59dd-4eb4-a7c9-c98966901e7d', 'fr', 'Tu vois qu’elle a un gobelet de café original. Que pourrais-tu dire en premier pour éveiller sa curiosité ?', '["« Il faut que je te demande un truc sur ce gobelet. »", "« Tu l’as trouvé où, ce gobelet ? »", "« Il a l’air sympa, ce gobelet. »", "« Tu viens souvent ici ? »"]'::jsonb, 'La mise en place crée de la curiosité avant de révéler la question.')
