insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36134173-386a-4742-a375-45b16eeb371f', 'fr', 'Que demande le fait de bien donner le ton ?', '["Attendre qu’elle te donne la permission ou des signaux pour continuer", "Choisir toi-même le sujet au lieu de rejoindre sa réalité", "Faire avancer l’échange sans attendre qu’elle mène"]'::jsonb, 'Donner le ton, c’est mener le sujet et la progression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('365d84da-247e-427e-a603-8e7d2900f73f', 'fr', 'Elle répond aimablement, mais dit : « Je vais bientôt devoir y aller. » Qu’est-ce que c’est ?', '["Politesse avec une limite en douceur : elle est dans l’échange mais signale qu’elle a peu de temps", "Ouverture : sa réponse aimable montre de l’intérêt, partir est juste une politesse", "Mitigé : son implication contredit son envie de partir"]'::jsonb, 'Elle est prévenante tout en signalant une limite ; prends-en acte et termine poliment l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3669c3ab-5f36-42cb-932f-6277589d1d8e', 'fr', 'Pourquoi est-il important de lire sa première réaction ?', '["Ça l’oblige à devenir réceptive", "Ça garde l’échange agréable pour vous deux", "Ça respecte son espace et ses signaux", "Ça évite de franchir des limites qu’elle n’a pas ouvertes"]'::jsonb, 'Bien lire sa réaction préserve l’aisance et le calme de part et d’autre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3717fc9d-129b-426e-a329-a0e904cfd1e1', 'fr', 'Elle répond en quelques mots, détourne le regard et change d’appui. Que fais-tu ensuite ?', '["Rester bref et prendre congé avec élégance", "Insister avec plus de questions pour l’impliquer", "Aller plus loin pour créer de l’attirance", "La complimenter pour la réchauffer"]'::jsonb, 'Des signaux neutres et polis veulent dire : ralentis ou retire-toi, pour respecter son confort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3763474f-7119-463b-a740-ab5dd1bb8606', 'fr', 'Tu abordes une femme qui lit dans un café. Quelle accroche garde une posture forte ?', '["« Désolé de te déranger, mais je voulais te dire bonjour. »", "« Cette place est prise ? »", "« Il a l’air intéressant, ce livre. Ça parle de quoi ? »", "« Excuse-moi, je peux te parler une minute ? »"]'::jsonb, 'Être direct et partir du principe qu’elle va répondre donne le ton, sans t’excuser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('381417bd-9910-49a2-b9c7-271afc73bcf9', 'fr', 'Quels résultats découlent de l’inaction ?', '["Un échec garanti", "Une protection contre le rejet", "Aucun lien, aucune possibilité", "Un regret qui dure"]'::jsonb, 'Ne rien faire garantit des occasions manquées et un regret durable.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38ade8d0-fc3e-4396-9791-5b19775afa46', 'fr', 'Tu l’abordes dans un endroit dégagé. Qu’est-ce que tu dois éviter ?', '["T’arrêter à une distance sociale avec une posture ouverte", "Bloquer son passage", "Arriver de façon visible, avec un angle de 45 degrés", "Garder environ un mètre d’espace"]'::jsonb, 'Bloquer le passage crée un malaise, même dans un espace dégagé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3a61650f-61dd-4d87-b302-9c1fad8a6217', 'fr', 'Pourquoi le jeu est-il important quand tu donnes le ton ?', '["Il réduit la pression et rend l’échange amusant plutôt que sérieux", "Un ton joueur crée de l’attirance par des émotions positives", "Il montre que tu es à l’aise", "Toutes les réponses ci-dessus"]'::jsonb, 'Tout est vrai : le jeu réduit la pression, crée des émotions positives et montre que tu es à l’aise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3aa54f55-0812-4c14-be64-8fed1f814fb4', 'fr', 'Quel signal distingue le mieux l’ouverture de la politesse ?', '["Sourire", "Le regard", "Te poser des questions en retour", "Hocher la tête"]'::jsonb, 'Le fait qu’elle te renvoie la balle indique l’intérêt plus clairement que le reste.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b44889c-1e0c-4a51-8846-e7d4ea05c95b', 'fr', 'Tu l’abordes dans une file d’attente. Elle dit : « En fait, je suis pressée. » Meilleure réponse ?', '["« Pas de souci, je voulais juste te dire bonjour », et partir en douceur", "T’excuser de l’avoir dérangée et reculer", "Ignorer ce qu’elle dit et continuer à parler"]'::jsonb, 'Ne force pas la conversation et ne t’excuse pas ; reste léger et passe à autre chose.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c06a35a-c102-4ca8-bce5-02e0afa2b5a6', 'fr', 'En boîte. Vous êtes allés dans un coin plus calme. Et ensuite ?', '["Continuer la conversation et proposer de se revoir une autre fois", "Prendre ses coordonnées maintenant, tant que l’élan est fort", "Proposer d’aller ailleurs ensemble", "Prendre son numéro ou proposer de continuer ensemble ailleurs, selon l’organisation et ses signaux"]'::jsonb, 'Un élan fort appelle une étape suivante : prends ses coordonnées, ou propose de continuer ailleurs si ses signaux disent oui.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c98c86a-c4c9-43a5-be53-6cad77bf34c5', 'fr', 'Quand faut-il mettre fin à un échange ?', '["Quand elle envoie des signaux froids : implication minimale, corps fermé, tourné ailleurs", "Quand les signaux polis persistent : réponses courtes, peu de réciprocité", "Quand le temps ou les circonstances rendent la suite inappropriée", "Toutes les réponses ci-dessus"]'::jsonb, 'Une sortie nette préserve son confort et ta posture quand l’implication n’est pas là.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3caf0039-8d00-42c1-8c5a-9b57ae2ac717', 'fr', 'Elle dit « En fait, je suis en train de faire un truc », mais continue de sourire, tournée vers toi.', '["Ouverture : le sourire l’emporte sur les mots", "Politesse : une limite posée avec respect", "Mitigé : insiste un peu", "Froideur : toute limite est un rejet"]'::jsonb, 'Une limite claire posée avec chaleur, c’est une façon polie de décrocher.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3dfb88ca-871e-4a7e-b233-6335a1bd949a', 'fr', 'Vous discutez et tu remarques que son amie reste dans les parages. Meilleure chose à faire ?', '["Ignorer son amie et continuer", "Rivaliser pour avoir son attention", "Inclure brièvement son amie, puis réévaluer", "Aller tout de suite plus loin"]'::jsonb, 'Inclure les autres réduit la tension sociale et te garde maître de la situation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3ebc28c1-d1f2-41ee-a393-af6d74a978a9', 'fr', 'Elle rit, mais continue de se tourner ailleurs. Qu’est-ce qui compte le plus ?', '["Son rire", "Ton accroche", "Son langage corporel", "Le lieu"]'::jsonb, 'Quand les signaux se contredisent, fie-toi aux signaux physiques ; laisse-lui de l’espace ou retire-toi si elle se tourne ailleurs.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40d53e0a-03ba-435a-8d62-e1fcb096eded', 'fr', 'Qu’est-ce qui rend une accroche indirecte naturelle et facile à accueillir ?', '["Dire quelque chose de malin ou d’impressionnant", "Un lieu ou un moment que vous vivez tous les deux", "Un timing parfait"]'::jsonb, 'Une situation partagée rend l’entrée en matière attendue et facile à suivre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'fr', 'Tu la vois dans un bar. Quelle est l’approche directe ?', '["Faire une remarque sur la musique ou les boissons pour lancer la conversation", "Croiser son regard et sourire", "« Tu as attiré mon regard, je voulais venir me présenter »"]'::jsonb, 'Les accroches directes annoncent clairement un intérêt amoureux dès le départ.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'fr', 'Tu vois une femme qui porte une montre vintage. Quelle accroche l’implique ?', '["« Salut, ça va ce soir ? »", "« Tu es jolie. »", "« Tu fais quoi dans la vie ? »", "« Elle a l’air d’avoir une histoire, cette montre. »"]'::jsonb, 'Une supposition précise l’oblige à s’impliquer et à répondre personnellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'fr', 'Dans une file d’attente, tu dis : « Tu as l’air bien trop calme pour cette queue. » Elle rit. Qu’est-ce qui marche ?', '["Tu as fait référence à la situation partagée", "Tu as créé un contraste joueur", "Tu as demandé la permission de parler"]'::jsonb, 'Une situation partagée plus une touche de jeu font vite baisser les résistances.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'fr', 'Pourquoi clarifier son intérêt par un seul geste direct vaut-il mieux que t’attarder ?', '["Ça raccourcit l’échange", "Ça montre que tu mènes", "Ça évite le rejet", "Ça lui donne de la clarté et le contrôle"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'fr', 'Pourquoi les accroches qui demandent son avis valorisent-elles les gens ?', '["En sollicitant son point de vue, tu dis clairement que son jugement compte", "Demander un avis montre ton intelligence émotionnelle et tes compétences sociales", "Les gens préfèrent parler d’eux qu’écouter"]'::jsonb, 'Les gens s’illuminent quand leur point de vue compte. Se sentir valorisé crée de l’implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'fr', 'Elle dit « En fait, j’étais sur le point de partir », mais elle s’attarde et continue de te poser des questions.', '["Une façon polie de décrocher", "Un signal mitigé qui penche vers l’ouverture", "Un signal froid adouci par politesse", "Un rejet net"]'::jsonb, 'S’attarder et rester curieuse montre de l’ouverture, malgré les contraintes pratiques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'fr', 'Elle sourit, répond positivement, mais dit : « En fait, je révise pour un examen. »', '["Ouverture : sa réponse positive montre de l’intérêt malgré les révisions", "Refus poli : elle est gentille, mais ses révisions posent une limite", "Test : elle veut voir si tu insistes ou si tu respectes ses priorités"]'::jsonb, 'Un ton positif peut être de la politesse ; une priorité annoncée est une limite. Souhaite-lui bonne chance et pars.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'fr', 'Elle répond avec enthousiasme, pose une question de relance, mais regarde sans arrêt son téléphone.', '["Ouverture : son implication verbale montre un vrai intérêt malgré le téléphone", "Politesse : regarder son téléphone contredit sa chaleur verbale et montre une attention partagée", "Mitigé : ses mots montrent de l’ouverture, mais son comportement suggère de la distraction"]'::jsonb, 'Des signaux mitigés demandent de s’ajuster ; continue brièvement pour voir si son attention revient.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'fr', 'Pourquoi est-il risqué de prendre la politesse pour de l’intérêt ?', '["Ça ralentit l’échange", "Ça lui met une pression dont elle ne veut pas", "Ça rend l’approche audacieuse"]'::jsonb, 'Son confort passe en premier ; sers-toi des signaux pour décider de continuer ou de lever le pied.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'fr', 'Elle échange chaleureusement, rit, pose des questions, mais dit : « En fait, j’ai un copain. »', '["Ouverture : son implication montre de l’intérêt, parler de son copain est un test", "Politesse : son échange chaleureux était de la gentillesse, son copain est une limite claire", "Mitigé : elle montre de l’intérêt, mais sa situation amoureuse crée un conflit"]'::jsonb, 'Elle était aimable, pas ouverte à une relation ; parler de son copain est une limite claire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'fr', 'Soirée. Elle est polie, mais tu n’es pas sûr de son intérêt. Quelles phrases aident ?', '["« Je vais me chercher un verre. Tu viens ? »", "« Elle est un peu ennuyeuse, cette soirée. »", "« Je te laisse profiter de la soirée. »", "« Viens, je te présente mes amis. »"]'::jsonb, 'Une proposition claire vérifie si elle a envie de bouger, de te rejoindre ou de continuer, sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
